classdef TestSolverAgainstLegacy < LdemTestCase
    %TESTSOLVERAGAINSTLEGACY  The new solver reproduces the legacy simulation.
    %
    %   Runs ldem.solver.simulate on the three reference cases and compares
    %   the final state with the one stored in the golden-master fixtures,
    %   which were generated by the (corrected) legacy driver. Covered:
    %   displacements, velocities, accelerations, bar forces, strains,
    %   damage state, damping switch, energies and the reaction and control
    %   node records of the beam.
    %
    %   Not compared, because the legacy value is not defined (see
    %   docs/known-issues/KNOWN_ISSUES.md): the external energy (never computed) and the
    %   energy vectors, which are compared after summing over the nodes.
    %
    %   See also TestMeshAgainstLegacy, TestMaterialAgainstLegacy.

    properties (TestParameter)
        caseName = {'tension101_elastic', 'tension101_damage', 'bending102'}
    end

    properties (Constant)
        RelTol = 1e-9
    end

    methods (Test, TestTags = {'Regression'})
        function finalStateMatchesLegacy(testCase, caseName)
            [fixture, state, ~] = testCase.runCase(caseName);
            s = fixture.state;
            nodal = @(x, y, z) [x(:), y(:), z(:)];

            testCase.compare(state.time, s.TIME, 'time');
            testCase.compare(state.displacement, nodal(s.U(2, :), s.V(2, :), s.W(2, :)), 'displacement');
            testCase.compare(state.previousDisplacement, nodal(s.U(1, :), s.V(1, :), s.W(1, :)), 'previous displacement');
            testCase.compare(state.velocity, nodal(s.VLX, s.VLY, s.VLZ), 'velocity');
            testCase.compare(state.acceleration, nodal(s.ACX, s.ACY, s.ACZ), 'acceleration');
            testCase.compare(state.force, nodal(s.FRX, s.FRY, s.FRZ), 'nodal force');
        end

        function barStateMatchesLegacy(testCase, caseName)
            [fixture, state, ~] = testCase.runCase(caseName);
            s = fixture.state;

            testCase.compare(state.strain, s.SS(:), 'strain');
            testCase.compare(state.strainRate, s.DSS(:), 'strain rate');
            testCase.compare(state.axialForce, s.F(:), 'axial force');
            testCase.compare(state.history.tensionStiffness, s.E2(:), 'tension stiffness');
            testCase.compare(state.history.maxStrain, s.EM(:), 'largest strain');
            testCase.verifyEqual(state.history.isUndamaged, logical(s.DM(:)), 'Damage flags differ.');
            testCase.verifyEqual(state.history.isUnbroken, logical(s.FS(:)), 'Rupture flags differ.');
        end

        function energiesMatchLegacy(testCase, caseName)
            [fixture, ~, record] = testCase.runCase(caseName);
            s = fixture.state;
            last = numel(record.energy.time);

            testCase.compare(record.energy.time(last), s.TIME, 'energy time');
            testCase.compare(record.energy.kinetic(last), sum(s.ENCN), 'kinetic energy');
            testCase.compare(record.energy.elastic(last), s.ENEL, 'elastic energy');
            testCase.compare(record.energy.damage(last), s.ENGD, 'damage energy');
            testCase.compare(record.energy.brokenBars(last), s.DEN, 'energy of broken bars');
            testCase.compare(record.energy.damageRate(last), s.DERIV, 'damage rate');
            testCase.compare(record.energy.damping(last), sum(s.ENDP), 'damping energy');
        end

        function beamReactionAndControlNodesMatchLegacy(testCase)
            [fixture, ~, record] = testCase.runCase('bending102');
            s = fixture.state;

            % Reaction of the last stored step (legacy SIM01.DAT keeps only that one).
            testCase.compare(record.reactions.force(end, 2), s.REACAOY, 'reaction Ry');
            row = sscanf(fixture.files.SIM01_DAT, '%f');
            testCase.compare(record.reactions.time(end), row(1), 'reaction time');
            testCase.compare(record.reactions.force(end, 2), row(2), 'reaction in SIM01');

            % Acceleration of the control nodes (legacy LET.POS: time, ax(node 1), ax(node 2)).
            pos = reshape(sscanf(fixture.files.LET_POS, '%f'), 3, []).';
            testCase.verifySize(record.controlNodes.time, [size(pos, 1) 1]);
            testCase.compare(record.controlNodes.time, pos(:, 1), 'control time');
            testCase.compare(record.controlNodes.acceleration(:, 1, 1), pos(:, 2), 'ax node 1');
            testCase.compare(record.controlNodes.acceleration(:, 2, 1), pos(:, 3), 'ax node 2');
        end

        function dampingSwitchIsExercised(testCase, caseName)
            % The reference cases change the damping inside the simulated
            % time, so the comparison above also validates the switch.
            fixture = load(fullfile(testCase.RepoRoot, 'tests', 'fixtures', caseName + ".mat"));
            c = fixture.caseDef;
            switchStep = round(c.dampingSwitchTime / c.dt);
            testCase.verifyNotEqual(c.damping1, c.damping2);
            testCase.verifyGreaterThanOrEqual(switchStep, 1);
            testCase.verifyLessThan(switchStep, c.nSteps);
        end
    end

    methods (Access = private)
        function [fixture, state, record] = runCase(testCase, caseName)
            fixture = load(fullfile(testCase.RepoRoot, 'tests', 'fixtures', caseName + ".mat"));
            c = fixture.caseDef;
            fieldFile = fullfile(testCase.RepoRoot, 'examples', 'beam_102', 'arquivo_3lc_rnao_cv05');
            params = ldem.Parameters( ...
                testId = c.test, ...
                seed = c.seed, ...
                moduleLength = c.moduleLength, ...
                nModules = c.modules, ...
                dampingInitial = c.damping1, ...
                dampingFinal = c.damping2, ...
                dampingSwitchTime = c.dampingSwitchTime, ...
                constitutiveDamping = c.con, ...
                dt = c.dt, ...
                totalTime = c.nSteps * c.dt, ...
                controlNodes = c.controlNodes, ...
                youngModulus = c.youngModulus, ...
                density = c.density, ...
                poissonRatio = c.poisson, ...
                fractureEnergy = c.fractureEnergy, ...
                criticalDistance = c.criticalDistance, ...
                randomFieldFile = fieldFile, ...
                output = struct('snapshotEvery', 0, 'controlNodesEvery', c.everyN, ...
                    'energyEvery', c.everyN, 'trackedBarEvery', 0));

            mesh = ldem.mesh.buildMesh(params);
            [barProps, history] = ldem.material.buildBarProperties(mesh, params);
            scenario = ldem.scenarios.fromTestId(params.testId);
            [state, record] = ldem.solver.simulate(params, mesh, barProps, history, scenario);
        end

        function compare(testCase, actual, expected, name)
            % Relative comparison with an absolute floor tied to the data scale.
            scale = max(abs(expected(:)));
            floor = 1e-12 * scale + realmin;
            testCase.verifyEqual(actual, expected, 'RelTol', testCase.RelTol, 'AbsTol', floor, ...
                sprintf('%s differs from the legacy result.', name));
        end
    end
end
